// MySQL is the durable source of truth. The application updates this read
// projection only after the corresponding transaction has committed.
var state = struct {
 sync.RWMutex
 users map[int64]User
 names map[string]int64
 icons map[int64][]byte
 streams map[int64]LivestreamModel
 tags map[int64][]Tag
 allTags []*Tag
 comments map[int64]map[int64]LivecommentModel
 reactions map[int64][]ReactionModel
 reports map[int64][]LivecommentReportModel
 words map[int64][]NGWord
 viewers map[int64]map[int64]int64
}{ }
var streamLocks sync.Map
func lockStream(id int64) func() {v,_:=streamLocks.LoadOrStore(id,&sync.Mutex{});m:=v.(*sync.Mutex);m.Lock();return m.Unlock}
func loadReadModel() error {
 var users []UserModel;var themes []ThemeModel;var streams []LivestreamModel;var tags []Tag;var links []LivestreamTagModel
 var comments []LivecommentModel;var reactions []ReactionModel;var reports []LivecommentReportModel;var words []NGWord
 var viewers []LivestreamViewerModel
 var icons []struct {UserID int64 "'`db:"user_id"`;Image []byte `db:"image"`}
 for _,q:=range []struct {dest interface{};sql string}{
 {&users,"SELECT * FROM users"},{&themes,"SELECT * FROM themes"},{&streams,"SELECT * FROM livestreams"},{&tags,"SELECT * FROM tags ORDER BY id"},{&links,"SELECT * FROM livestream_tags ORDER BY id"},
 {&comments,"SELECT * FROM livecomments"},{&reactions,"SELECT * FROM reactions ORDER BY id"},{&reports,"SELECT * FROM livecomment_reports ORDER BY id"},{&words,"SELECT * FROM ng_words ORDER BY id"},
 {&viewers,"SELECT user_id,livestream_id,created_at FROM livestream_viewers_history"},{&icons,"SELECT user_id,image FROM icons"},
 } {if err:=dbConn.Select(q.dest,q.sql);err!=nil{return err}}
 fallback,err:=os.ReadFile(fallbackImage);if err!=nil{return err}
 state.Lock();defer state.Unlock()
 state.users=make(map[int64]User);state.names=make(map[string]int64);state.icons=make(map[int64][]byte);state.streams=make(map[int64]LivestreamModel);state.tags=make(map[int64][]Tag);state.allTags=make([]*Tag,0,len(tags))
 state.comments=make(map[int64]map[int64]LivecommentModel);state.reactions=make(map[int64][]ReactionModel);state.reports=make(map[int64][]LivecommentReportModel);state.words=make(map[int64][]NGWord);state.viewers=make(map[int64]map[int64]int64)
 themeMap:=make(map[int64]Theme);for _,t:=range themes{themeMap[t.UserID]=Theme{ID:t.ID,DarkMode:t.DarkMode}}
 for _,i:=range icons{state.icons[i.UserID]=i.Image}
 for _,u:=range users{img,ok:=state.icons[u.ID];if !ok{img=fallback;state.icons[u.ID]=img};state.users[u.ID]=User{ID:u.ID,Name:u.Name,DisplayName:u.DisplayName,Description:u.Description,Theme:themeMap[u.ID],IconHash:fmt.Sprintf("%x",sha256.Sum256(img))};state.names[u.Name]=u.ID}
