 go func(){log.Fatal(http.ListenAndServe("10.99.0.11:9080",nil))}()
 c,err:=net.ListenUDP("udp4",&net.UDPAddr{Port:53});if err!=nil{log.Fatal(err)};c.SetReadBuffer(4<<20);c.SetWriteBuffer(4<<20)
 for i:=0;i<4;i++{go func(){buf:=make([]byte,4096);for{n,addr,err:=c.ReadFromUDP(buf);if err!=nil{log.Print(err);continue};resp,err:=reply(buf[:n]);if err==nil{c.WriteToUDP(resp,addr)}}}()};select{}
}
